mapper.select:
SELECT
    id, tenant_id AS tenantId, query_hash AS queryHash, data_version AS dataVersion, abc_type AS abcType,
    bucket, current_sales_per AS currentSalesPer, current_sku_per AS currentSkuPer,
    compare_sales_per AS compareSalesPer, compare_sku_per AS compareSkuPer,
    set_sales_per AS setSalesPer, set_sku_per AS setSkuPer,
    current_sku AS currentSku, compare_sku AS compareSku, change_sku AS changeSku,
    current_sales AS currentSales, stock_quantity AS stockQuantity, stock_quantity_per AS stockQuantityPer
FROM diag_result_abc_bucket
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
  AND abc_type = #{abcType}
ORDER BY CASE bucket WHEN 'A' THEN 1 WHEN 'B' THEN 2 WHEN 'C' THEN 3 ELSE 9 END

SELECT
    id, tenant_id AS tenantId, query_hash AS queryHash, data_version AS dataVersion, abc_type AS abcType,
    aa_num AS aaNum, ab_num AS abNum, ac_num AS acNum, an_num AS anNum, at_num AS atNum,
    ba_num AS baNum, bb_num AS bbNum, bc_num AS bcNum, bn_num AS bnNum, bt_num AS btNum,
    ca_num AS caNum, cb_num AS cbNum, cc_num AS ccNum, cn_num AS cnNum, ct_num AS ctNum
FROM diag_result_abc_matrix
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
  AND abc_type = #{abcType}

